// a is a row-major Float64Array, N x N: element (i, j) at a[i * N + j]
// goal: colSums[j] = sum over all rows i of a[i][j]
function columnSums(a, N) {
  const colSums = new Array(N).fill(0);
  for (let j = 0; j < N; j++) {        // outer: column
    for (let i = 0; i < N; i++) {      // inner: row
      colSums[j] += a[i * N + j];      // inner stride = N elements
    }
  }
  return colSums;
}
